param()
$ErrorActionPreference='Stop';[Console]::InputEncoding=[Text.Encoding]::UTF8;[Console]::OutputEncoding=[Text.Encoding]::UTF8
$p=$null;$source=$null;$target=$null
try{
 $p=[Console]::In.ReadToEnd()|ConvertFrom-Json;if($p.scope -cne 'SCCRM-HQ-SALES-IMPORT-V1' -or $p.branch -cnotin @('001','003','004','005') -or $p.doc -cnotmatch '^[SR][0-9]{10}-[0-9]{7}$'){throw 'SALES_VERIFY_SCOPE_REFUSED'}
 function Open($t){$b=New-Object Data.SqlClient.SqlConnectionStringBuilder;$b['Data Source']=$t.server;$b['Initial Catalog']='AdaAcc';$b['User ID']=$t.user;$b['Password']=$t.password;$b['Connect Timeout']=5;$b['Application Name']='SCCRM-Sales-Destination-ReadOnly';$d=New-Object Data.SqlClient.SqlConnection $b.ConnectionString;$d.Open();$t.password='';return $d}
 $source=Open $p.source;$target=Open $p.target
 function Read($db,[string]$physical,$cols,$keys){$q=$db.CreateCommand();$q.CommandTimeout=10;$q.CommandText='SET LOCK_TIMEOUT 750;SET DEADLOCK_PRIORITY LOW;SELECT '+(@($cols|ForEach-Object{'['+$_+']'}) -join ',')+' FROM dbo.['+$physical+'] WHERE FTShdDocNo=@doc ORDER BY '+(@($keys|ForEach-Object{'['+$_+']'}) -join ',');$null=$q.Parameters.Add('@doc',[Data.SqlDbType]::VarChar,20);$q.Parameters['@doc'].Value=$p.doc;$a=New-Object Data.SqlClient.SqlDataAdapter $q;$dt=New-Object Data.DataTable;try{$null=$a.Fill($dt);return ,$dt}finally{$a.Dispose();$q.Dispose()}}
 function Hash($dt){$rows=@();foreach($row in $dt.Rows){$values=@();foreach($v in $row.ItemArray){$values+=if($v -is [DBNull]){$null}elseif($v -is [DateTime]){$v.ToString('o',[Globalization.CultureInfo]::InvariantCulture)}elseif($v -is [double]){$v.ToString('R',[Globalization.CultureInfo]::InvariantCulture)}elseif($v -is [IFormattable]){$v.ToString($null,[Globalization.CultureInfo]::InvariantCulture)}else{[string]$v}};$rows+=,@($values)};$sha=[Security.Cryptography.SHA256]::Create();try{[BitConverter]::ToString($sha.ComputeHash([Text.Encoding]::UTF8.GetBytes((ConvertTo-Json -InputObject @($rows) -Depth 6 -Compress)))).Replace('-','').ToLowerInvariant()}finally{$sha.Dispose()}}
 $tables=@();foreach($table in @('TPSTSalHD','TPSTSalDT','TPSTSalRC','TPSTSalPD','TPSTSalPG','TPSTSalPH','TPSTSalInvCsm','TPSTVoidDT')){
  $cols=@($p.columns|Where-Object{$_.table_name -ceq $table}|ForEach-Object{if($_.column_name -cnotmatch '^[A-Za-z0-9_]+$' -or $_.column_name -match 'pin|password|secret|token'){throw 'SALES_VERIFY_COLUMN_REFUSED'};[string]$_.column_name});$keys=@($p.keys.$table)
  $a=Read $source ('SCCRM_SalesExport_'+$table) $cols $keys;$b=Read $target $table $cols $keys;$ha=Hash $a;$hb=Hash $b;if($a.Rows.Count -ne $b.Rows.Count -or $ha -cne $hb){throw 'SALES_DESTINATION_DIFFERENT'};if($table -ceq 'TPSTSalHD' -and $b.Rows.Count -ne 1){throw 'SALES_DESTINATION_HEADER_REQUIRED'};$tables+=@{table=$table;rows=$b.Rows.Count;hash=$hb}
 }
 @{ok=$true;branch=$p.branch;doc=$p.doc;at=[DateTime]::UtcNow.ToString('o');tables=$tables;pinRead=$false;dataWrites=0}|ConvertTo-Json -Depth 6 -Compress
}catch{@{ok=$false;code=$(if($_.Exception.Message -cmatch '^SALES_[A-Z_]+$'){$_.Exception.Message}else{'SALES_VERIFY_FAILED'});type=$_.Exception.GetBaseException().GetType().Name}|ConvertTo-Json -Compress;exit 1}finally{if($source){$source.Dispose()};if($target){$target.Dispose()};if($p){$p.source.password='';$p.target.password=''}}
